class Solution {
public:
    bool validWordSquare(vector<string>& words) {
        size_t n = words.size();
        for (size_t r = 0; r < n; ++r) {
            for (size_t c = 0; c < words[r].size(); ++c) {
                if (c >= n || r >= words[c].size() || words[r][c] != words[c][r]) {
                    return false;
                }
            }
        }
        return true;
    }
};

class Solution {
    public boolean validWordSquare(List<String> words) {
        int n = words.size();
        for (int r = 0; r < n; r++) {
            String row = words.get(r);
            for (int c = 0; c < row.length(); c++) {
                if (c >= n || r >= words.get(c).length() || row.charAt(c) != words.get(c).charAt(r)) {
                    return false;
                }
            }
        }
        return true;
    }
}

